#include "resultant_lib.hpp"
Pol invert_mod(Pol a,const Pol&mod){Pol r0=mod,r1=rem(a,mod),t0,t1{1};while(!r1.empty()){auto qr=fastdiv(r0,r1);Pol t2=padd(t0,pscale(fastmul(qr.first,t1),4));r0=move(r1);r1=move(qr.second);t0=move(t1);t1=move(t2);}if(r0.size()!=1)throw runtime_error("nonunit inverse modulo l");return rem(pscale(t0,inv(r0[0])),mod);}
BP tshift(BP a,int n){if(a.r.empty())return a;a.r.insert(a.r.begin(),n,Pol{});return a;}
int main(int argc,char**argv){if(argc<4){cerr<<"usage: build_exceptional norm_poly.txt square_equations.txt output.txt\n";return 2;}try{init();selfchecks();ifstream in(argv[1]),lin(argv[2]);if(!in||!lin)throw runtime_error("cannot open exceptional input files");Pol l=readp(lin);int nx,nt;in>>nx>>nt;vector<BP>a(nx);for(int i=0;i<nx;i++){a[i].r.resize(nt);for(auto&r:a[i].r)r=readp(in);a[i]=bmod(a[i],l);}if(!a[108].r.empty()||!a[107].r.empty()||a[106].r.size()!=2||!a[106].r[0].empty())throw runtime_error("exceptional leading shape");Pol bb=a[106].r[1],bi=invert_mod(bb,l);if(rem(fastmul(bb,bi),l)!=Pol{1})throw runtime_error("inverse check");Pol deriv(l.size()-1);for(int j=1;j<(int)l.size();j++)deriv[j-1]=mul(j%5,l[j]);if(gcdp(l,deriv)!=Pol{1})throw runtime_error("l not squarefree");if(gcdp(l,a[105].r[0])!=Pol{1})throw runtime_error("odd degree 105 branch not established");cerr<<"PASS l squarefree degree 11; t!=0: degree 106; t=0: degree 105 with unit leading coefficient\n";vector<BP>u(54);u[0].r={{1}};vector<BP>eq;for(int j=1;j<=58;j++){BP f=bmod(tshift(bpol(a[106-j],bi),j-1),l);for(int r=max(1,j-53);r<j&&r<=53;r++){int s=j-r;if(r>s)continue;f=bmod(badd(f,bscale(bmul(u[r],u[s]),r==s?4:3)),l);}if(j<=53)u[j]=bmod(bscale(f,3),l);else{int power=0;while(!f.r.empty()&&f.r[0].empty()){f.r.erase(f.r.begin());power++;}cerr<<"eq "<<j<<" removed t^"<<power<<" degree_t "<<f.r.size()-1<<" degree_s "<<f.ns()-1<<"\n";eq.push_back(f);}}
ofstream out(argv[3]);if(!out)throw runtime_error("cannot open output file");printp(out,l);printp(out,bb);printp(out,bi);printp(out,a[105].r[0]);out<<eq.size()<<'\n';for(auto&p:eq)writebp(out,p);out.flush();Pol comb=l;vector<pair<int,int>> pairs{{0,1},{0,2},{0,3},{0,4},{1,2},{1,3}};int count=0;for(auto [ia,ib]:pairs){int m=eq[ia].r.size()-1,n=eq[ib].r.size()-1;int bound=n*(eq[ia].ns()-1)+m*(eq[ib].ns()-1);int N=bound+1;cerr<<"pair "<<ia<<" "<<ib<<" resultant degree bound "<<bound<<"\n";vector<Pol>va,vb;for(auto&r:eq[ia].r)va.push_back(geom_eval(r,N));for(auto&r:eq[ib].r)vb.push_back(geom_eval(r,N));Pol values(N);for(int i=0;i<N;i++){Pol aa(m+1),bb(n+1);for(int j=0;j<=m;j++)aa[j]=va[j][i];for(int j=0;j<=n;j++)bb[j]=vb[j][i];values[i]=formal_resultant(aa,bb,m,n);}Pol R=geom_interpolate(values);if(geom_eval(R,N)!=values)throw runtime_error("exceptional interpolation mismatch");for(int i=0;i<8;i++){F s=ex[(N+11+7*i)%NN];Pol aa,bb;for(auto&r:eq[ia].r)aa.push_back(ev(r,s));for(auto&r:eq[ib].r)bb.push_back(ev(r,s));if(ev(R,s)!=formal_resultant(aa,bb,m,n))throw runtime_error("extra grid point");}Pol rr=rem(R,l);comb=gcdp(comb,rr);cerr<<"resultant degree "<<R.size()-1<<"; gcd with l degree "<<comb.size()-1<<"\n";out<<ia<<' '<<ib<<' '<<bound<<'\n';printp(out,R);printp(out,rr);out.flush();count++;if(comb==Pol{1}){cerr<<"UNIT GCD: exceptional branch excluded for t!=0\n";break;}}if(comb!=Pol{1})throw runtime_error("exceptional unit-gcd exclusion not established");out<<"FINAL "<<count<<'\n';printp(out,comb);cerr<<"DONE exceptional branch\n";
return 0;}catch(exception&e){cerr<<"FAIL "<<e.what()<<"\n";return 1;}}
